"""A network in the KROME format, advanced by the implicit solvers of the chemistry module.

Reads a KROME network file (for instance ``networks/react_galaxy_ism`` of KROME, or a
variant of it), sets up a row of gas cells without hydrodynamics and advances them with

* the vmapped Diffrax Kvaerno5 (the default solver), and
* the per-cell Rosenbrock23 Warp kernel generated by gradsolve from the same right-hand side,

then prints both results and their difference. The temperature is evolved with the
abundances (thermochemistry). Run it from the repository root:

    python examples/chemistry_krome_network.py --network /path/to/krome/networks/react_galaxy_ism \\
        --krome-data /path/to/krome/data --draine 1 --shield-habing-dust
                                    # both solvers, as a KROME build with -photoBins=10 -shieldHabingDust
    python examples/chemistry_krome_network.py --network ... --krome-data /path/to/krome/data --draine 1 \\
        --shield-habing-dust --no-metal-table   # without KROME's metal cooling table above 1e4 K
    python examples/chemistry_krome_network.py --network ... --no-kernel    # Kvaerno5 only, without KROME's data

The cells span ``n_H`` = 1 to 1e4 cm^-3 and start atomic, with carbon and silicon singly
ionised. The heating and cooling are KROME's; the metal lines and the metal cooling table are
read from the data folder of a KROME installation (``--krome-data``). Both solvers look the
table up (the kernel receives it as an array); the first build of the kernel takes a minute or
two and is cached. ``--isothermal`` holds the temperature at ``--temperature``
instead (Kvaerno5 only: the kernel of the module integrates the temperature with the species).

The radiation field is, as in KROME, a spectrum in energy bins: ``--draine X`` sets the
interstellar field of Draine times ``X`` in ten bins between 5 and 13.6 eV, from which the
rates and the heating of the photo-reactions and the Habing flux of the dust terms follow
(the cross sections come from KROME's database, hence ``--krome-data``). Without it the
photo-reactions are off and ``--habing-field`` is the Habing flux. ``--shield-habing-dust``,
``--shielding`` and ``--column-density-method`` are the build options of KROME of the same
names, and ``--free-free`` adds the bremsstrahlung of the ions (KROME's ``-cooling=FF``),
which matters for gas above about 1e7 K.
"""

import argparse
import time

import jax

jax.config.update("jax_enable_x64", True)

import jax.numpy as jnp
import numpy as np

from astronomix import (
    SimulationConfig,
    SimulationParams,
    construct_primitive_state,
    finalize_config,
    get_registered_variables,
)
from astronomix._modules._chemistry._chemistry import make_vector_field, update_chemistry
from astronomix._modules._cooling._cooling import (
    get_pressure_from_temperature,
    get_temperature_from_pressure,
)
from astronomix.option_classes.simulation_config import FINITE_VOLUME, NATIVE_JAX, BackendConfig
from astronomix._modules._chemistry._krome_photo import habing_field, photo_spectrum
from astronomix.setup_helpers import build_chemistry_from_network_file

# Code units of this example: density in m_p cm^-3, temperature in K, time in Myr.
NUMBER_DENSITY_UNIT_CGS = 1.0
TEMPERATURE_UNIT_KELVIN = 1.0
TIME_UNIT_SECONDS = 3.15576e13
GAMMA = 5.0 / 3.0

# Abundances per hydrogen nucleus at the start; the electrons balance the charge and
# every species not listed starts at 1e-20.
INITIAL_ABUNDANCES = {
    "H": 0.9998, "H+": 1.0e-4, "H2": 5.0e-7, "He": 8.5e-2, "He+": 1.0e-8,
    "C": 1.0e-5, "C+": 1.3e-4, "O": 3.2e-4, "O+": 1.0e-8, "Si": 1.0e-7, "Si+": 1.7e-6,
}


def build(arguments, use_kernel):
    """Return the initial state and what ``update_chemistry`` needs to advance it."""
    chemistry_config, chemistry_params, species_names = build_chemistry_from_network_file(
        arguments.network,
        "krome",
        number_density_unit_cgs=NUMBER_DENSITY_UNIT_CGS,
        temperature_unit_kelvin=TEMPERATURE_UNIT_KELVIN,
        time_unit_seconds=TIME_UNIT_SECONDS,
        cosmic_ray_rate=3.0e-17,
        fuv_field=arguments.habing_field,
        thermochemistry=arguments.thermochemistry,
        cooling_courant=10.0,
        absolute_tolerance=arguments.atol,
        relative_tolerance=arguments.rtol,
        max_steps=4096,
        krome_h2_formation_on_dust=not arguments.no_h2_on_dust,
        krome_data_folder=arguments.krome_data,
        krome_metal_table=not arguments.no_metal_table,
        krome_photo_bins=(
            None if arguments.draine is None else photo_spectrum("draine", 5.0, 13.6, 10, scale=arguments.draine)
        ),
        krome_user_variables=dict((name, float(value)) for name, value in (item.split("=") for item in arguments.user_variable)),
        krome_shield_habing_dust=arguments.shield_habing_dust,
        krome_shielding=arguments.shielding,
        krome_column_density_method=arguments.column_density_method,
        krome_free_free_cooling=arguments.free_free,
    )

    if use_kernel:
        from astronomix._modules._chemistry._warp_stiff import build_fused_core_solver

        cc, cp = chemistry_config, chemistry_params
        vector_field = make_vector_field(
            cp.network, cp.rate_modifier_a, cp.rate_modifier_b, cp.cosmic_ray_rate, cp.fuv_field,
            cp.visual_extinction, cc.thermochemistry, GAMMA, cp.dust_to_gas_ratio,
            cp.hydrogen_molecule_formation_rate_coefficient, cc.hydrogen_index,
            cc.molecular_hydrogen_index, cc.electron_index, cc.atomic_oxygen_index,
            cc.ionized_hydrogen_index, cc.helium_index, cc.ionized_carbon_index, cc.co_cooling,
            cc.carbon_monoxide_index, cp.co_cooling_table, cp.co_cooling_bounds,
        )
        solver = build_fused_core_solver(
            vector_field, cc.number_of_chemical_species + 1,
            rtol=float(cp.rtol), atol=float(cp.atol), max_steps=cc.max_steps,
            cache_key=(
                "example-krome-network", arguments.network, arguments.thermochemistry, arguments.krome_data,
                arguments.no_metal_table, arguments.draine, arguments.shield_habing_dust, arguments.shielding,
                arguments.column_density_method, arguments.habing_field, arguments.no_h2_on_dust,
                tuple(arguments.user_variable), arguments.free_free,
            ),
        )
        chemistry_config = chemistry_config._replace(stiff_core_solver="warp", stiff_core_fn=solver)

    config = SimulationConfig(
        dimensionality=1,
        solver_mode=FINITE_VOLUME,
        backend_config=BackendConfig(backend=NATIVE_JAX),
        box_size=1.0,
        num_cells=arguments.cells,
        progress_bar=False,
        chemistry_config=chemistry_config,
    )
    params = SimulationParams(t_end=1.0, gamma=GAMMA, chemistry_params=chemistry_params)
    registered_variables = get_registered_variables(config)

    hydrogen_mass_fraction = chemistry_params.hydrogen_mass_fraction
    metal_mass_fraction = chemistry_params.metal_mass_fraction
    hydrogen_nuclei = jnp.logspace(0.0, 4.0, arguments.cells)  # n_H [cm^-3]
    density = hydrogen_nuclei / hydrogen_mass_fraction
    pressure = get_pressure_from_temperature(
        density,
        jnp.full(arguments.cells, arguments.temperature / TEMPERATURE_UNIT_KELVIN),
        hydrogen_mass_fraction,
        metal_mass_fraction,
    )
    state = construct_primitive_state(
        config=config,
        registered_variables=registered_variables,
        density=density,
        velocity_x=jnp.zeros(arguments.cells),
        gas_pressure=pressure,
    )
    abundances = {name: INITIAL_ABUNDANCES.get(name, 1.0e-20) for name in species_names}
    charge = {name: name.count("+") - name.count("-") for name in species_names if name != "E"}
    abundances["E"] = sum(charge[name] * abundances[name] for name in charge)
    start = registered_variables.chemistry_species_index
    for index, name in enumerate(species_names):
        state = state.at[start + index].set(abundances[name] * hydrogen_nuclei)

    config = finalize_config(config, state.shape)
    return state, config, params, registered_variables, tuple(species_names), np.asarray(hydrogen_nuclei)


def run(arguments, use_kernel):
    """Advance the cells; return abundances per H nucleus and the temperature."""
    state, config, params, registered_variables, names, hydrogen_nuclei = build(arguments, use_kernel)
    start_time = time.perf_counter()
    for step in range(arguments.steps):
        state = update_chemistry(state, registered_variables, config.chemistry_config, params, arguments.time_step)
        if step == 0:
            jax.block_until_ready(state)
            first_step = time.perf_counter() - start_time
    jax.block_until_ready(state)
    elapsed = time.perf_counter() - start_time

    start = registered_variables.chemistry_species_index
    species = np.asarray(state[start : start + len(names)])
    chemistry_params = params.chemistry_params
    temperature = TEMPERATURE_UNIT_KELVIN * np.asarray(
        get_temperature_from_pressure(
            state[registered_variables.density_index],
            state[registered_variables.pressure_index],
            chemistry_params.hydrogen_mass_fraction,
            chemistry_params.metal_mass_fraction,
        )
    )
    return species / hydrogen_nuclei, temperature, names, hydrogen_nuclei, first_step, elapsed


def report(label, abundances, temperature, names, hydrogen_nuclei):
    columns = [name for name in ("H", "H2", "H+", "E", "C+", "C", "O+", "Si+") if name in names]
    print(f"\n{label}")
    print("   n_H [cm^-3]     T [K] " + "".join(f"{'x(' + name + ')':>11s}" for name in columns))
    shown = np.unique(np.linspace(0, len(hydrogen_nuclei) - 1, min(8, len(hydrogen_nuclei))).astype(int))
    for cell in shown:
        values = "".join(f"{abundances[names.index(name), cell]:11.3e}" for name in columns)
        print(f"   {hydrogen_nuclei[cell]:11.3e} {temperature[cell]:9.2f} {values}")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--network", required=True, help="network file in the KROME format")
    parser.add_argument("--krome-data", default=None, help="the data folder of KROME: metal line data and metal cooling table "
                        "for the thermochemistry (without it the metals cool through [C II] and [O I] only)")
    parser.add_argument("--cells", type=int, default=16)
    parser.add_argument("--steps", type=int, default=20)
    parser.add_argument("--time-step", type=float, default=0.05, help="length of a step [Myr]")
    parser.add_argument("--temperature", type=float, default=50.0, help="initial temperature [K] (held with --isothermal); avoid the temperature limits of the fits (30, 100, 200 K, ...), where a rate jumps")
    parser.add_argument("--habing-field", type=float, default=1.7, help="Habing flux of the dust terms (not with --draine)")
    parser.add_argument("--draine", type=float, default=None, metavar="X", help="radiation field: Draine's times X in ten bins "
                        "between 5 and 13.6 eV, as KROME's krome_set_photoBin_draineLin (needs --krome-data)")
    parser.add_argument("--user-variable", action="append", default=[], metavar="NAME=VALUE", help="value of a @common "
                        "variable of the file other than user_crate, e.g. user_myfluxLW=2e-10 (repeatable)")
    parser.add_argument("--shield-habing-dust", action="store_true", help="attenuate the Habing flux by dust (KROME's -shieldHabingDust)")
    parser.add_argument("--shielding", choices=("DB96", "WG11", "R14"), default=None, help="H2 self-shielding returned by "
                        "krome_fshield in the rates of the file (KROME's -shielding)")
    parser.add_argument("--column-density-method", choices=("DEFAULT", "JEANS"), default="DEFAULT", help="column density of "
                        "the shielding terms (KROME's -columnDensityMethod)")
    parser.add_argument("--isothermal", action="store_true", help="hold the temperature instead of integrating it with the "
                        "species (Kvaerno5 only)")
    parser.add_argument("--thermochemistry", action="store_true", help=argparse.SUPPRESS)  # the default; kept for old command lines
    parser.add_argument("--no-metal-table", action="store_true", help="without the tabulated metal cooling above 1e4 K")
    parser.add_argument("--free-free", action="store_true", help="add the bremsstrahlung of the atomic ions (KROME's "
                        "-cooling=FF), the main coolant of ionised gas above about 1e7 K")
    parser.add_argument("--no-h2-on-dust", action="store_true", help="without the H2 formation on dust (Jura)")
    parser.add_argument("--rtol", type=float, default=1.0e-6)
    parser.add_argument("--atol", type=float, default=1.0e-12)
    parser.add_argument("--no-kernel", action="store_true", help="skip the Warp kernel (gradsolve, warp-lang)")
    arguments = parser.parse_args()
    arguments.thermochemistry = not arguments.isothermal

    if arguments.draine is not None and arguments.krome_data is None:
        parser.error("--draine needs --krome-data (the cross sections of the photo-reactions are in KROME's database)")
    print(f"network: {arguments.network}")
    print(f"devices: {jax.devices()}")
    print(
        f"{arguments.cells} cells, {arguments.steps} steps of {arguments.time_step} Myr "
        f"({arguments.steps * arguments.time_step:g} Myr), "
        f"{'thermochemistry on' if arguments.thermochemistry else f'temperature held at {arguments.temperature:g} K'}, "
        f"rtol {arguments.rtol:g}, atol {arguments.atol:g}"
    )

    reference, temperature, names, hydrogen_nuclei, first, elapsed = run(arguments, False)
    print(f"species ({len(names)}): {' '.join(names)}")
    if arguments.draine is not None:
        spectrum = photo_spectrum("draine", 5.0, 13.6, 10, scale=arguments.draine)
        print(f"radiation: Draine field x {arguments.draine:g} in 10 bins, Habing flux "
              f"{habing_field(spectrum['left'], spectrum['right'], spectrum['intensity']):.4f}"
              f"{', attenuated by dust' if arguments.shield_habing_dust else ''}")
    report("Diffrax Kvaerno5 (vmapped)", reference, temperature, names, hydrogen_nuclei)
    print(f"   first step {first:.1f} s (compilation included), all steps {elapsed:.1f} s")
    if arguments.no_kernel:
        return
    if not arguments.thermochemistry:
        print("\nThe Warp kernel of the chemistry module integrates the temperature with the species: "
              "run without --isothermal to compare the two solvers.")
        return
    print("\nBuilding the per-cell kernel: a minute or two the first time, cached afterwards (--no-kernel skips it).")
    kernel, kernel_temperature, _, _, first, elapsed = run(arguments, True)
    report("Rosenbrock23 Warp kernel (gradsolve), one thread per cell", kernel, kernel_temperature, names, hydrogen_nuclei)
    print(f"   first step {first:.1f} s (kernel build included), all steps {elapsed:.1f} s")

    significant = reference > 1.0e-10
    difference = np.abs(np.log10(kernel[significant] / reference[significant]))
    temperature_difference = np.abs(kernel_temperature / temperature - 1.0)
    print(
        f"\nkernel against Kvaerno5: largest |dlog10 x| {difference.max():.1e} dex over the abundances above 1e-10, "
        f"largest relative temperature difference {temperature_difference.max():.1e}"
    )


if __name__ == "__main__":
    main()
